r_skin_conductance_microsiemens=7.8, # Significant arousal\n    eye_tracking_logo_dwell_time_ms=1450 # 1.45 seconds on brand logo\n)\n\nprint(f\"Frontal Asymmetry Index (Approach Valence): {neuro_report['frontal_asymmetry_index']}\")\nprint(f\"Emotional Arousal Index: {neuro_report['emotional_arousal_score']}\")\nprint(f\"Visual Attention Share: {neuro_report['visual_attention_share_pct']}%\")\nprint(f\"Neural Purchase Intent Score: {neuro_report['neural_purchase_intent_score']}/100\")\nprint(f\"Verdict: {neuro_report['executive_verdict']}\")",
